"use client";

import ApartmentOutlinedIcon from "@mui/icons-material/ApartmentOutlined";
import AssignmentTurnedInOutlinedIcon from "@mui/icons-material/AssignmentTurnedInOutlined";
import CloseIcon from "@mui/icons-material/Close";
import DashboardOutlinedIcon from "@mui/icons-material/DashboardOutlined";
import ExpandLess from "@mui/icons-material/ExpandLess";
import ExpandMore from "@mui/icons-material/ExpandMore";
import GroupOutlinedIcon from "@mui/icons-material/GroupOutlined";
import MenuIcon from "@mui/icons-material/Menu";
import NightsStayIcon from "@mui/icons-material/NightsStay";
import PaletteOutlinedIcon from "@mui/icons-material/PaletteOutlined";
import PaymentsOutlinedIcon from "@mui/icons-material/PaymentsOutlined";
import PersonOutlineOutlinedIcon from "@mui/icons-material/PersonOutlineOutlined";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import SettingsOutlinedIcon from "@mui/icons-material/SettingsOutlined";
import TimeToLeaveOutlinedIcon from "@mui/icons-material/TimeToLeaveOutlined";
import WorkOutlineOutlinedIcon from "@mui/icons-material/WorkOutlineOutlined";
import WbSunnyIcon from "@mui/icons-material/WbSunny";
import {
  AppBar,
  Box,
  Button,
  Collapse,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Drawer,
  IconButton,
  List,
  ListItemIcon,
  ListItemButton,
  ListItemText,
  Toolbar,
  Typography
} from "@mui/material";
import { usePathname, useRouter } from "next/navigation";
import Link from "next/link";
import { ReactNode, useEffect, useState } from "react";
import { useThemeMode } from "@/components/ThemeModeProvider";
import dicConstant from "@/constants/Constant.json";

const drawerWidth = 250;

type MenuChild = {
  label: string;
  href: string;
};

type MenuItem = {
  label: string;
  href?: string;
  icon: ReactNode;
  submenuKey?: "employees" | "leave" | "payroll";
  children?: MenuChild[];
};

const navItems: MenuItem[] = [
  { label: "Dashboard", href: "/dashboard", icon: <DashboardOutlinedIcon /> },
  {
    label: "Employees",
    submenuKey: "employees",
    icon: <GroupOutlinedIcon />,
    children: [
      { label: "Employee List", href: "/employees" },
      { label: "Add Employee", href: "/employees/new" },
      { label: "Department Master", href: "/departments" },
      { label: "Department Master Inline", href: "/departments-inline" }
    ]
  },
  {
    label: "Leave",
    submenuKey: "leave",
    icon: <TimeToLeaveOutlinedIcon />,
    children: [
      { label: "Leave Requests", href: "/leave" },
      { label: "Apply Leave", href: "/leave/apply" }
    ]
  },
  {
    label: "Payroll",
    submenuKey: "payroll",
    icon: <PaymentsOutlinedIcon />,
    children: [
      { label: "Payroll Overview", href: "/payroll" },
      { label: "Run Payroll", href: "/payroll/run" },
      { label: "Payslips", href: "/payroll/payslips" }
    ]
  },
  { label: "Attendance", href: "/attendance", icon: <AssignmentTurnedInOutlinedIcon /> },
  { label: "Theme", href: "/theme", icon: <PaletteOutlinedIcon /> },
  { label: "Profile", href: "/profile", icon: <PersonOutlineOutlinedIcon /> },
  { label: "Settings", href: "/settings", icon: <SettingsOutlinedIcon /> }
];

// Provides the main app chrome with responsive sidebar navigation and top bar.
export default function AppShell({ children }: { children: ReactNode }) {
  // Functional responsibility:
  // - Provide primary application shell: app bar, responsive drawer, and nested content area.
  // Inputs:
  // - children route content rendered in main panel.
  // Output:
  // - Responsive navigation with submenu state and theme-toggle interaction.
  // Failure behavior:
  // - Unknown routes simply result in no selected nav item; shell still renders.
  const pathname = usePathname();
  const router = useRouter();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [desktopOpen, setDesktopOpen] = useState(true);
  const [intIsLogoutDialogOpen, setIntIsLogoutDialogOpen] = useState(0);
  const [openSubmenus, setOpenSubmenus] = useState({
    employees:
      pathname.startsWith("/employees") ||
      pathname.startsWith("/departments") ||
      pathname.startsWith("/departments-inline"),
    leave: pathname.startsWith("/leave"),
    payroll: pathname.startsWith("/payroll")
  });
  const { mode, toggleMode } = useThemeMode();

  useEffect(() => {
    if (
      pathname.startsWith("/employees") ||
      pathname.startsWith("/departments") ||
      pathname.startsWith("/departments-inline")
    ) {
      setOpenSubmenus((prev) => ({ ...prev, employees: true }));
    }
    if (pathname.startsWith("/leave")) {
      setOpenSubmenus((prev) => ({ ...prev, leave: true }));
    }
    if (pathname.startsWith("/payroll")) {
      setOpenSubmenus((prev) => ({ ...prev, payroll: true }));
    }
  }, [pathname]);

  const toggleSubmenu = (key: "employees" | "leave" | "payroll") => {
    setOpenSubmenus((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const isChildActive = (href: string) => pathname === href;

  const isParentActive = (children: MenuChild[]) => children.some((child) => pathname.startsWith(child.href));
  const strLogoutPath = "/logout";

  const handleLogoutClick = () => {
    setIntIsLogoutDialogOpen(1);
  };

  const handleLogoutCancel = () => {
    setIntIsLogoutDialogOpen(0);
  };

  const handleLogoutConfirm = () => {
    setIntIsLogoutDialogOpen(0);
    setMobileOpen(false);
    router.push(strLogoutPath);
  };

  const drawerContent = (
    <Box sx={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <Toolbar sx={{ display: "flex", justifyContent: "space-between" }}>
        <Box sx={{ display: "flex", alignItems: "center" }}>
          <ApartmentOutlinedIcon sx={{ mr: 1 }} />
          <Typography variant="h6" fontWeight={700}>
            HRMS
          </Typography>
        </Box>
        <IconButton
          aria-label="Close navigation menu"
          onClick={() => {
            setMobileOpen(false);
            setDesktopOpen(false);
          }}
          sx={{ display: { xs: "inline-flex", md: "inline-flex" } }}
        >
          <CloseIcon />
        </IconButton>
      </Toolbar>
      <Box sx={{ flex: 1, overflowY: "auto" }}>
        <List>
          {navItems.map((item) => {
            if (!item.children) {
              return (
                <ListItemButton
                  key={item.label}
                  component={Link}
                  href={item.href ?? "#"}
                  selected={pathname === item.href}
                  onClick={() => setMobileOpen(false)}
                >
                  <ListItemIcon
                    sx={{
                      color: pathname === item.href ? "primary.main" : "text.secondary",
                      transition: "color 0.2s ease"
                    }}
                  >
                    {item.icon}
                  </ListItemIcon>
                  <ListItemText primary={item.label} />
                </ListItemButton>
              );
            }

            const submenuKey = item.submenuKey as "employees" | "leave" | "payroll";
            const open = openSubmenus[submenuKey];
            const active = isParentActive(item.children);

            return (
              <Box key={item.label}>
                <ListItemButton selected={active} onClick={() => toggleSubmenu(submenuKey)}>
                  <ListItemIcon
                    sx={{
                      color: active ? "primary.main" : "text.secondary",
                      transition: "color 0.2s ease"
                    }}
                  >
                    {item.icon}
                  </ListItemIcon>
                  <ListItemText primary={item.label} />
                  {open ? <ExpandLess /> : <ExpandMore />}
                </ListItemButton>
                <Collapse in={open} timeout="auto" unmountOnExit>
                  <List component="div" disablePadding>
                    {item.children.map((child) => (
                      <ListItemButton
                        key={child.href}
                        component={Link}
                        href={child.href}
                        selected={isChildActive(child.href)}
                        onClick={() => setMobileOpen(false)}
                        sx={{ pl: 6 }}
                      >
                        <ListItemIcon
                          sx={{
                            minWidth: 30,
                            color: isChildActive(child.href) ? "primary.main" : "text.secondary",
                            transition: "color 0.2s ease"
                          }}
                        >
                          <WorkOutlineOutlinedIcon fontSize="small" />
                        </ListItemIcon>
                        <ListItemText primary={child.label} />
                      </ListItemButton>
                    ))}
                  </List>
                </Collapse>
              </Box>
            );
          })}
        </List>
      </Box>
      <Box sx={{ borderTop: "1px solid", borderColor: "divider", py: 0.4, px: 0.8 }}>
        <List disablePadding>
          <ListItemButton onClick={handleLogoutClick} sx={{ py: 0.4 }}>
            <ListItemIcon sx={{ color: "text.secondary", transition: "color 0.2s ease" }}>
              <LogoutOutlinedIcon />
            </ListItemIcon>
            <ListItemText primary="Logout" />
          </ListItemButton>
        </List>
      </Box>
      <Dialog
        open={Boolean(intIsLogoutDialogOpen)}
        onClose={handleLogoutCancel}
        aria-labelledby="logout-confirm-title"
        aria-describedby="logout-confirm-description"
      >
        <DialogTitle id="logout-confirm-title">Confirm Logout</DialogTitle>
        <DialogContent>
          <DialogContentText id="logout-confirm-description">
            Are you sure you want to logout from the application?
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleLogoutCancel}>Cancel</Button>
          <Button onClick={handleLogoutConfirm} color="error" variant="contained" autoFocus>
            Confirm Logout
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );

  return (
    <Box sx={{ display: "flex" }}>
      {/* Top bar with title, mobile nav trigger, and theme mode toggle */}
      <AppBar
        position="fixed"
        sx={{
          width: { md: desktopOpen ? `calc(100% - ${drawerWidth}px)` : "100%" },
          ml: { md: desktopOpen ? `${drawerWidth}px` : 0 }
        }}
      >
        <Toolbar>
          <Box sx={{ width: 48, display: "flex", justifyContent: "flex-start" }}>
            <IconButton
              color="inherit"
              edge="start"
              onClick={() => setMobileOpen(!mobileOpen)}
              sx={{ display: { md: "none" } }}
            >
              <MenuIcon />
            </IconButton>
            <IconButton
              color="inherit"
              edge="start"
              onClick={() => setDesktopOpen((prev) => !prev)}
              sx={{ display: { xs: "none", md: "inline-flex" } }}
            >
              <MenuIcon />
            </IconButton>
          </Box>
          <Box sx={{ flexGrow: 1, display: "flex", justifyContent: "center" }}>
            <Typography variant="h6" sx={{ textAlign: "center" }}>
              Human Resource Management System
            </Typography>
          </Box>
          <Box sx={{ width: 48, display: "flex", justifyContent: "flex-end" }}>
            <IconButton color="inherit" onClick={toggleMode} aria-label="Toggle theme">
              {mode === "light" ? <NightsStayIcon /> : <WbSunnyIcon />}
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>

      <Box component="nav" sx={{ width: { md: desktopOpen ? drawerWidth : 0 }, flexShrink: { md: 0 } }}>
        {/* Temporary drawer on small screens */}
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={() => setMobileOpen(false)}
          ModalProps={{ keepMounted: true }}
          sx={{
            display: { xs: "block", md: "none" },
            "& .MuiDrawer-paper": {
              boxSizing: "border-box",
              width: drawerWidth,
              display: "flex",
              flexDirection: "column",
              overflow: "hidden"
            }
          }}
        >
          {drawerContent}
        </Drawer>
        {/* Permanent drawer on desktop */}
        <Drawer
          variant="permanent"
          open
          sx={{
            display: { xs: "none", md: desktopOpen ? "block" : "none" },
            "& .MuiDrawer-paper": {
              boxSizing: "border-box",
              width: drawerWidth,
              display: "flex",
              flexDirection: "column",
              overflow: "hidden"
            }
          }}
        >
          {drawerContent}
        </Drawer>
      </Box>

      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 3,
          width: { md: desktopOpen ? `calc(100% - ${drawerWidth}px)` : "100%" },
          minHeight: "100vh"
        }}
      >
        <Toolbar />
        {children}
      </Box>
    </Box>
  );
}
